import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, smoothstep, sub, mul } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';
import * as primitives from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Box3, Vector3, Color } = ctx.THREE;

  // ---- Background Plane ----
  const planeGeom = new PlaneGeometry(7, 0.35);
  const planeMat = new MeshStandardNodeMaterial({
    color: new Color('#111117'),
    roughness: 0.6,
    metalness: 0.2,
    transparent: true,
  });

  // Alpha gradient for edge fades
  const uvNode = uv();
  const u = uvNode.x;
  const leftMask = sub(1, smoothstep(0, 0.09, u));
  const rightMask = smoothstep(0.91, 1, u);
  const alphaNode = mul(leftMask, rightMask);
  planeMat.alphaNode = alphaNode;

  const background = new Mesh(planeGeom, planeMat);
  background.position.set(0, 0, 0);

  // ---- Ribbon Content Strip ----
  const strip = new Group();

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  let cursor = 0;
  const baseUnit = 0.25;
  const gap = 2 * baseUnit; // 0.5 units gap on each side of tick
  const tickWidth = 0.02;
  const tickHeight = 0.14;
  const tickColor = new Color('#ff2a38');

  // Helper to compute width of an Object3D
  const computeWidth = (obj) => {
    const box = new Box3();
    box.setFromObject(obj);
    const size = new Vector3();
    box.getSize(size);
    return size.x;
  };

  items.forEach((item, idx) => {
    // Create text object
    const txt = ctx.fontAtlas.createText(item.text || item, {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'left',
      letterSpacing: 0.06 * 13,
    });
    strip.add(txt);
    const txtWidth = computeWidth(txt);
    txt.position.set(cursor + txtWidth / 2, 0, 0.02);
    cursor += txtWidth + gap;

    // Tick mark (except after last item)
    const tickGeom = new PlaneGeometry(tickWidth, tickHeight);
    const tickMat = new MeshStandardNodeMaterial({
      color: tickColor,
      emissive: tickColor,
      emissiveIntensity: 1.5,
      metalness: 0,
      roughness: 0.5,
      transparent: true,
    });
    const tick = new Mesh(tickGeom, tickMat);
    tick.position.set(cursor, 0, 0);
    strip.add(tick);
    cursor += gap;
  });

  const stripWidth = cursor;

  // Duplicate strip for seamless loop
  const stripClone = strip.clone();
  stripClone.position.x = stripWidth;
  // Adjust cloned tick materials (share same material is fine)

  // ---- Assemble Node ----
  const node = new Group();
  node.add(background);
  node.add(strip);
  node.add(stripClone);

  // ---- Hairline borders (top & bottom) ----
  const hairColor = new Color('#23232b');
  const hairThickness = 0.006;
  const hairGeom = new PlaneGeometry(7, hairThickness);
  const hairMat = new MeshBasicNodeMaterial({ color: hairColor });
  const topHair = new Mesh(hairGeom, hairMat);
  const bottomHair = new Mesh(hairGeom, hairMat);
  topHair.position.set(0, 0.35 / 2, 0.001);
  bottomHair.position.set(0, -0.35 / 2, 0.001);
  node.add(topHair);
  node.add(bottomHair);

  // ---- Apply Cinematic Primitives ----
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((p) => {
      const fn = ctx.primitives[p.name];
      if (fn) {
        const handle = fn(node, p.params || {});
        primitiveHandles.push(handle);
      }
    });
  }

  // ---- Cleanup ----
  node.userData.cleanup = () => {
    // Dispose geometries & materials
    planeGeom.dispose();
    planeMat.dispose();
    hairGeom.dispose();
    hairMat.dispose();
    // Dispose tick materials (unique per tick)
    strip.traverse((obj) => {
      if (obj.isMesh && obj.material && obj.material.dispose) {
        obj.geometry && obj.geometry.dispose();
        obj.material.dispose();
      }
    });
    // Cleanup primitives
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });
    // Kill any GSAP timelines (none used directly)
    gsap.globalTimeline.clear();
  };

  // Store handlers placeholder (no interaction needed)
  node.userData.handlers = {};

  return node;
}
